raw.document:
query CandidateProductsByTitle {
  products(first: 10, query: "title:\"Borderlands Discovery Four\" OR title:\"Cloud Needle Tsolikouri\"") {
    nodes {
      id
      title
      handle
      status
      totalInventory
      vendor
      productType
      onlineStoreUrl
      variants(first: 10) {
        nodes {
          id
          title
          availableForSale
          inventoryQuantity
        }
      }
    }
  }
}

