query CandidateProducts($ids: [ID!]!) {
  nodes(ids: $ids) {
    ... on Product {
      id
      title
      handle
      status
      totalInventory
      vendor
      productType
      onlineStoreUrl
      variants(first: 10) {
        nodes {
          id
          title
          availableForSale
          inventoryQuantity
        }
      }
    }
  }
}

